<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Money movement</p><h1 class="mt-2 text-3xl font-black">Payments & wallet</h1><p class="mt-2 text-sm text-slate-400">Provider order states, verified deposits, and idempotent refunds.</p></div>
  <div class="mt-5 grid gap-3 sm:grid-cols-3"><div class="glass-card rounded-2xl p-4"><p class="text-[10px] uppercase tracking-widest text-slate-500">Captured deposits</p><p class="mt-2 text-xl font-black text-neon-400"><?= h(format_money($totals['captured_minor'])) ?></p></div><div class="glass-card rounded-2xl p-4"><p class="text-[10px] uppercase tracking-widest text-slate-500">Captured orders</p><p class="mt-2 text-xl font-black"><?= h(number_format($totals['captured_count'])) ?></p></div><div class="glass-card rounded-2xl p-4"><p class="text-[10px] uppercase tracking-widest text-slate-500">Pending refunds</p><p class="mt-2 text-xl font-black text-amber-200"><?= h(number_format($totals['pending_refunds'])) ?></p></div></div>
  <form method="get" class="glass-card mt-5 flex flex-wrap items-end gap-3 rounded-2xl p-4"><input type="hidden" name="page" value="admin-wallet"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search email, payment or receipt<input class="form-control mt-2" name="q" maxlength="100" value="<?= h($search) ?>" placeholder="Search payment records"></label><label class="min-w-36 text-xs font-bold text-slate-400">Status<select class="form-control mt-2" name="status"><option value="all">All</option><?php foreach(['created','authorized','captured','failed','refunded'] as $state): ?><option value="<?= h($state) ?>" <?= $statusFilter===$state?'selected':'' ?>><?= h(ucfirst($state)) ?></option><?php endforeach; ?></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Filter</button></form>
  <div class="glass-card mt-5 overflow-hidden rounded-2xl"><?php if(!$payments): ?><p class="p-10 text-center text-sm text-slate-500">No payment orders match this filter.</p><?php else: ?><div class="table-wrap"><table class="w-full text-left text-xs"><thead class="bg-black/20 text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-4">Player / receipt</th><th class="px-4 py-4">Provider references</th><th class="px-4 py-4">Amount</th><th class="px-4 py-4">Status</th><th class="px-4 py-4">Created</th><th class="px-4 py-4">Refund action</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($payments as $item): ?><tr><td class="px-4 py-4"><p class="font-bold"><?= h($item['display_name'] ?: $item['email']) ?></p><p class="mt-1 font-mono text-[10px] text-slate-500"><?= h($item['receipt']) ?></p></td><td class="px-4 py-4 font-mono text-[10px] text-slate-500"><p><?= h($item['provider_order_id'] ?: 'Order pending') ?></p><p class="mt-1"><?= h($item['provider_payment_id'] ?: 'No payment ID') ?></p></td><td class="px-4 py-4 font-black"><?= h(format_money((int)$item['amount_minor'])) ?></td><td class="px-4 py-4"><span class="badge <?= $item['status']==='captured'?'badge-open':($item['status']==='failed'?'badge-closed':'badge-soon') ?>"><?= h($item['status']) ?></span></td><td class="px-4 py-4 text-[10px] text-slate-500"><?= h(date('d M Y · g:i A',strtotime((string)$item['created_at'].' UTC'))) ?></td><td class="px-4 py-4"><?php if($item['status']==='captured'): ?><form method="post" action="<?= h(app_url('index.php?action=admin-payment-refund')) ?>" class="flex items-center gap-2" data-confirm="Request this refund through Razorpay? Wallet funds will be debited and held until the provider confirms."><?= csrf_field() ?><input type="hidden" name="payment_order_id" value="<?= h($item['id']) ?>"><input class="form-control w-24 !px-2 !py-2 text-[10px]" type="number" name="amount_rupees" min="0.01" max="<?= h(format_money_input((int)$item['amount_minor'])) ?>" step="0.01" required placeholder="Amount"><button class="rounded-lg border border-rose-300/15 px-2 py-2 text-[10px] font-bold text-rose-200">Refund</button></form><?php else: ?><span class="text-[10px] text-slate-600">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
  <?php if($pageCount>1): ?><nav class="mt-4 flex flex-wrap gap-2" aria-label="Payment pages"><?php for($n=1;$n<=$pageCount;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$pageNumber?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-wallet','q'=>$search,'status'=>$statusFilter,'p'=>$n,'ledger_q'=>$ledgerSearch,'ledger_type'=>$ledgerType,'ledger_p'=>$ledgerPage]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
  <section class="glass-card mt-5 rounded-2xl p-5"><div><p class="text-[10px] font-black uppercase tracking-widest text-violet-300">Payment event delivery</p><h2 class="mt-1 text-lg font-black">Verified webhooks</h2></div><?php if(!$webhookEvents): ?><p class="mt-4 text-xs text-slate-500">Webhook events will appear when Razorpay is configured.</p><?php else: ?><div class="table-wrap mt-4"><table class="w-full text-left text-xs"><thead class="text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="pb-3">Provider event ID</th><th class="pb-3">Event</th><th class="pb-3">State</th><th class="pb-3">Received</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($webhookEvents as $event): ?><tr><td class="py-3 font-mono text-[10px] text-slate-500"><?= h($event['provider_event_id']) ?></td><td class="py-3 font-bold"><?= h($event['event_type']) ?></td><td class="py-3"><?= h($event['status']) ?></td><td class="py-3 text-[10px] text-slate-500"><?= h(date('d M · g:i A',strtotime((string)$event['received_at'].' UTC'))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
  <section class="glass-card mt-5 rounded-2xl p-5">
    <div><p class="text-[10px] font-black uppercase tracking-widest text-violet-300">Immutable ledger</p><h2 class="mt-1 text-lg font-black">Wallet transactions</h2><p class="mt-1 text-xs text-slate-500"><?= h(number_format($ledgerTotal)) ?> entries · balance changes are never edited in place.</p></div>
    <form method="get" class="mt-4 flex flex-wrap items-end gap-3"><input type="hidden" name="page" value="admin-wallet"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search player, reference, or transaction key<input class="form-control mt-2" name="ledger_q" maxlength="100" value="<?= h($ledgerSearch) ?>"></label><label class="min-w-40 text-xs font-bold text-slate-400">Transaction type<select class="form-control mt-2" name="ledger_type"><option value="all">All types</option><?php foreach(['deposit','entry_fee','entry_refund','prize','withdrawal_reserve','withdrawal_release','withdrawal_paid','admin_adjustment'] as $type): ?><option value="<?= h($type) ?>" <?= $ledgerType===$type?'selected':'' ?>><?= h(str_replace('_',' ',$type)) ?></option><?php endforeach; ?></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Filter ledger</button></form>
    <?php if(!$ledger): ?><p class="mt-4 text-xs text-slate-500">No ledger entries match this filter.</p><?php else: ?><div class="table-wrap mt-4"><table class="w-full text-left text-xs"><thead class="text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="pb-3">Player / transaction</th><th class="pb-3">Type</th><th class="pb-3">Amount</th><th class="pb-3">Available Δ</th><th class="pb-3">Reserved Δ</th><th class="pb-3">After · available / reserved</th><th class="pb-3">Reference / time</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($ledger as $entry): ?><tr><td class="py-3"><p class="font-bold"><?= h($entry['display_name'] ?: $entry['email']) ?></p><p class="mt-1 max-w-52 truncate font-mono text-[9px] text-slate-600"><?= h($entry['idempotency_key']) ?></p></td><td class="py-3 uppercase text-violet-200"><?= h(str_replace('_',' ',$entry['transaction_type'])) ?></td><td class="py-3 font-black"><?= h(format_money((int)$entry['amount_minor'])) ?></td><td class="py-3 <?= (int)$entry['available_delta_minor']<0?'text-rose-200':'text-neon-400' ?>"><?= h(format_money((int)$entry['available_delta_minor'])) ?></td><td class="py-3 text-slate-300"><?= h(format_money((int)$entry['reserved_delta_minor'])) ?></td><td class="py-3 text-slate-300"><?= h(format_money((int)$entry['available_after_minor'])) ?> / <?= h(format_money((int)$entry['reserved_after_minor'])) ?></td><td class="py-3 text-[10px] text-slate-500"><p><?= h($entry['reference_type'] ?: '—') ?> · <?= h($entry['reference_id'] ?: '—') ?></p><p class="mt-1"><?= h(date('d M Y · g:i A',strtotime((string)$entry['created_at'].' UTC'))) ?></p></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <?php if($ledgerPages>1): ?><nav class="mt-4 flex flex-wrap gap-2" aria-label="Ledger pages"><?php for($n=1;$n<=$ledgerPages;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$ledgerPage?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-wallet','q'=>$search,'status'=>$statusFilter,'p'=>$pageNumber,'ledger_q'=>$ledgerSearch,'ledger_type'=>$ledgerType,'ledger_p'=>$n]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
  </section>
</main>
